  "knowledge": "Conservation Status Categories",
  "description": "Illustrates the conservation status values and their meanings.",
  "definition": "Values range from 'Excellent' (recently conserved, no issues), 'Good' (stable with minor issues), 'Fair' (stable but with noticeable issues), 'Poor' (active deterioration), to 'Critical' (severe deterioration requiring immediate intervention)."
}

{
  "id": 60,
  "knowledge": "Compliance Level",
  "description": "Categorizes the Environmental Compliance Index (ECI) score into human-readable levels.",
  "definition": "Assigns a level based on the 'Environmental Compliance Index (ECI)' score: 'Excellent' for scores > 7, 'Good' for scores between 4 and 7 (inclusive), and 'Poor' for scores <= 4."
}

{
  "id": 39,
  "knowledge": "Environmental Compliance Index (ECI)",
  "description": "Measures how well current environmental conditions meet the requirements for an artifact.",
  "definition": "Calculated as: 10 - (absolute difference in temperature from ideal + absolute difference in humidity from ideal / 5 + 'Environmental Risk Factor' / 2). Higher values are better."
}

{
  "id": 56,
  "knowledge": "Conservation Priority Level",
  "description": "Classifies artifacts into priority levels based on their CPI scores.",
  "definition": "Based on the 'Conservation Priority Index (CPI)': 'High Priority' for scores > 7, 'Medium Priority' for scores between 4 and 7, and 'Low Priority' for scores <= 4."
}

{
  "id": 58,
  "knowledge": "Exposure Status",
  "description": "Determines whether an artifact's current humidity exceeds its defined sensitivity threshold.",
  "definition": "Classified as 'Over Exposure' if the current relative humidity exceeds the 'Humidity Exposure Thresholds' defined for its sensitivity level, otherwise 'Within Limits'."
}
